create table if not exists public.jobs (id text primary key, source text not null, source_id text, title text not null, company text not null, location text, remote boolean default true, url text not null, description text, salary text, posted_at timestamptz, discovered_at timestamptz not null default now(), match_score integer default 0, status text not null default 'new', tags text[] default '{}'); create index if not exists jobs_discovered_at_idx on public.jobs(discovered_at desc); alter table public.jobs enable row level security; -- server uses service role key; never expose it to client.